#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""ТІЛЬКИ ЧИТАННЯ. Як записане внутрішнє переміщення (купівля валюти): обидві сторони."""
import collections, os, sys, urllib.parse
BASE = "/root/unitex-finrep"
sys.path.insert(0, os.path.join(BASE, "engine"))
os.chdir(BASE)
from odata_client import ODataClient
c = ODataClient()

def get(p): return c._get(urllib.parse.quote(p, safe="/?&=$,'"))

def page(ent, sel=None):
    out, skip = [], 0
    while True:
        p = "/%s?$format=json&$top=1000&$skip=%d" % (ent, skip)
        if sel: p += "&$select=" + ",".join(sel)
        b = get(p)["value"]; out += b
        if len(b) < 1000: return out
        skip += 1000

def d10(x):
    x = str(x or ""); return "" if (not x or x.startswith("0001-01-01")) else x[:10]

def nm(e):
    return {r["Ref_Key"]: (r.get("Description") or "").strip()
            for r in page(e, ["Ref_Key", "Description"])}

acc = nm("Catalog_ВидОплаты"); cur = nm("Catalog_Валюты")

print("=== чи використовується Document_КупляПродажаВалюты ===")
try:
    kp = page("Document_КупляПродажаВалюты")
    print("   записів:", len(kp))
    if kp:
        print("   поля:", ", ".join(k for k in kp[0] if not k.endswith("@navigationLinkUrl")))
except Exception as e:
    print("   ПОМИЛКА", type(e).__name__)

vp = [r for r in page("Document_ВнутреннееПеремещение")
      if r.get("Posted") and not r.get("DeletionMark")]
vp.sort(key=lambda r: d10(r.get("Date")))
print("\n=== ПОВНИЙ ЗАПИС трьох переміщень різного типу ===")
want = [("Банк Юнітекс Ейч-Ді", "Маерск USD"),
        ("Банк Юнітекс Ейч-Ді", "Банк Юнітекс Ейч-Ді Восток"),
        ("Банк Юнітекс Ейч-Ді Восток", "Банк Cr String Cycle LLC")]
shown = set()
for r in reversed(vp):
    k = (acc.get(r.get("ВидОплаты_Key"), ""), acc.get(r.get("ВидОплаты2_Key"), ""))
    if k not in want or k in shown:
        continue
    shown.add(k)
    print("\n  --- №%s від %s : %s → %s ---"
          % ((r.get("Number") or "").lstrip("0"), d10(r.get("Date")), k[0], k[1]))
    for f in sorted(r):
        if f.endswith("@navigationLinkUrl") or f in ("Ref_Key", "DataVersion"):
            continue
        v = r[f]
        if v in (None, "", 0, False, "0001-01-01T00:00:00"):
            continue
        if str(v).startswith("00000000-0000"):
            continue
        if f.endswith("_Key"):
            v = "%s  [%s]" % (acc.get(v) or cur.get(v) or "?", str(v)[:8])
        print("      %-32s %s" % (f, v))
    if len(shown) == len(want):
        break

print("\n=== чи є в переміщеннях друга сума/курс (тобто дві сторони) ===")
keys = collections.Counter()
for r in vp:
    for f, v in r.items():
        if f.endswith("@navigationLinkUrl"): continue
        if v not in (None, "", 0, False, "0001-01-01T00:00:00") and not str(v).startswith("00000000-0000"):
            keys[f] += 1
print("   поля, заповнені хоч раз (з %d док.):" % len(vp))
for f, n in sorted(keys.items()):
    print("      %-34s %d" % (f, n))
PYEOF
